"""Persist the AI-assisted, actually viewed DEV review and verify retained links.

This records observations made after opening all 30 generated contact sheets and
six full native raw frames. It does not rerun an enhancement or a model, select a
production configuration, count vehicles, create ground truth, or read hold-out.
"""
from pathlib import Path
from collections import Counter
import gzip
import hashlib
import json
from PIL import Image

HERE = Path(__file__).resolve().parent
SOURCE = HERE.parent
VARIANTS = ['raw', 'gamma_070', 'exposure_125', 'contrast_125', 'unsharp_s1_a05']
FRAMES = [0, 7, 14, 29, 239, 2277, 2337, 2397, 2457, 2516, 7072, 7132, 7192, 7252, 7311]

# These are explicit review annotations, not labels generated by model output.
OBSERVATIONS = {
    0: ('Jalan bagian depan relatif kosong pada crop; lampu jauh dan area rumah kanan tetap terang. Gamma memperlihatkan tekstur aspal dan tepi gelap lebih jelas, sedangkan contrast menghitamkan shadow.',
        'Kelima varian hanya mengeluarkan person di area rumah kanan. Identitas fisik objek kecil tersebut belum dipastikan. Tidak ada dasar untuk menyimpulkan seluruh frame tidak mengandung kendaraan.'),
    7: ('Motor/rider memasuki sisi kanan sangat dekat, terpotong frame dan sebagian tertutup teks; blur gerak tampak pada semua varian. Gamma membuka bagian gelap, tetapi tidak memulihkan detail yang sudah kabur.',
        'Kelima varian mengeluarkan person besar; tidak ada bbox motorcycle. Gamma/exposure/unsharp person bbox mencapai tepi kanan. Ini kasus masuk-frame dan komponen yang perlu replay kontinu.'),
    14: ('Satu motor/rider dekat terlihat bergerak ke kiri dengan blur kuat; body motor masih terlihat pada gambar raw dan gamma. Gamma mencerahkan aspal/body, contrast menggelapkan area bawah.',
        'Raw mempunyai motorcycle bbox confidence0.402; gamma dan contrast tidak mempunyai bbox motorcycle. Exposure mempertahankan bbox lebih kecil0.259, unsharp mempertahankan0.343. Kehilangan bbox kendaraan pada gamma adalah regresi per-frame yang konkret.'),
    29: ('Motor/rider kini lebih jauh ke kiri, body terlihat kecil dan sebagian gelap. Gamma mengangkat aspal/body shadow tanpa menghilangkan blur.',
        'Raw/gamma/exposure/unsharp mengeluarkan person+motorcycle di area motor tersebut; contrast mengeluarkan person tanpa motorcycle. Bbox motorcycle gamma lebih sempit daripada raw: BC/line-crossing tidak boleh dianggap otomatis ekuivalen.'),
    239: ('Lampu dan siluet kecil terlihat jauh di kiri; bagian depan jalan gelap. Gamma membuka tekstur jalan; exposure membuat sumber lampu lebih dominan, contrast menghapus detail shadow.',
        'Semua varian hanya mengeluarkan person kecil di rumah kanan. Tipe dan jumlah kendaraan di sekitar lampu jauh UNKNOWN pada bukti sparse ini; tidak dilabeli false vehicle atau dihitung.'),
    2277: ('Motor/rider sangat dekat di kanan dengan body/area lampu depan tampak kabur, sebagian tertutup teks; sorotan jalan dan flare ungu sangat kuat. Gamma mengangkat body/shadow; exposure memperluas area putih jalan/lampu.',
        'Semua varian mengeluarkan person besar. Gamma dan unsharp menambah car bbox sekitar[688,456,763,545], tepat di area depan motor yang terlihat; ini konflik kategori/komponen, bukan mobil baru yang telah terbukti. Tidak ada motorcycle bbox pada kelima varian.'),
    2337: ('Motor mendekat dengan lampu ungu tampak di kiri; area kecil di sekitar[496,430,519,463] dekat rumah tengah tetap gelap. Gamma memperjelas jalan tetapi tidak menyelesaikan glare.',
        'Kelima varian mengeluarkan person+motorcycle pada motor kiri. Raw/exposure/unsharp juga mengeluarkan motorcycle kecil di rumah tengah; gamma/contrast tidak. Identitas fisik bbox kecil tersebut UNKNOWN; hilangnya bbox belum otomatis baik/buruk.'),
    2397: ('Sorotan terang di kiri menutupi sebagian detail objek; terdapat objek kecil bercahaya di sebelah kiri sorotan. Exposure memperkuat glare/area putih; gamma mengangkat jalan tanpa mengungkap tipe objek secara pasti.',
        'Raw/gamma/contrast tidak mengeluarkan deteksi. Exposure mengeluarkan car sekitar[175,429,202,457]; unsharp motorcycle pada posisi hampir sama serta motorcycle kecil di rumah tengah. Perbedaan label wajib diselidiki temporal; objek/lampu UNKNOWN tidak dianggap false vehicle.'),
    2457: ('Dua sumber lampu sangat terang terlihat mengarah ke kamera; body kendaraan di antaranya gelap dan tidak cukup rinci untuk menentukan kategorinya. Gamma tidak memulihkan detail di pusat lampu, exposure memperluas bidang terang.',
        'Kelima varian mempunyai nol deteksi pada frame ini. Ini kegagalan observasi sparse di kondisi glare, bukan bukti tidak ada kendaraan dan bukan missed-count yang telah diukur.'),
    2516: ('Jalan depan kembali lebih gelap; lampu/siluet jauh tetap kecil. Gamma membuat permukaan jalan dan roadside lebih terlihat; contrast menghitamkan shadow.',
        'Kelima varian hanya mengeluarkan person kecil di rumah kanan. Belum ada bukti temporal untuk identitas kendaraan jauh atau manfaat downstream.'),
    7072: ('Satu truck sangat dekat memenuhi kanan frame; roda, underbody dan rangka samping tampak. Gamma memperlihatkan underbody/shadow lebih terang; exposure juga menaikkan jalan/lampu jauh. Blur dan objek terpotong tetap ada.',
        'Raw/gamma/exposure/unsharp mengeluarkan dua bbox truck yang tumpang tindih pada truck dekat yang sama; contrast satu bbox. Pengurangan bbox contrast belum membuktikan deduplikasi passage lebih baik. Gamma tidak menyelesaikan risiko duplikasi ini.'),
    7132: ('Truck terlihat menjauh di kiri; chassis belakang/roda dan jalan terangkat pada gamma, tetapi detail masih kabur. Lampu rumah kanan dan glare jauh tetap kuat.',
        'Kelima varian mengeluarkan truck pada area truck dan person di rumah kanan, dengan bbox truck hampir sama. Perubahan confidence tidak dijadikan ukuran kualitas atau alasan pemilihan.'),
    7192: ('Motor/rider berjubah terang terlihat menjauh di kiri; jalan mendapat sorotan terang. Gamma memperlihatkan shadow sekitar roda/tepi jalan, exposure membuat jalan dan lampu rumah lebih putih.',
        'Kelima varian mengeluarkan person+motorcycle di motor kiri. Gamma tidak mengeluarkan person rumah kanan yang muncul pada raw/exposure/unsharp; contrast menambah motorcycle kecil sekitar[485,424,520,465]. Identitas objek kecil UNKNOWN.'),
    7252: ('Car putih tampak menjauh di tengah-kiri; two-wheeler kecil berada lebih jauh di kiri. Detail bodi car semakin pucat pada exposure. Gamma membuka jalan/roadside, tetapi tidak mengubah ketidakjelasan two-wheeler kecil.',
        'Kelima varian mengeluarkan car putih dan truck bbox di area gelap kanan car/roadside, yang belum terkonfirmasi sebagai unit truck tersendiri. Raw/gamma/unsharp memberi label bicycle pada objek kecil kiri; exposure motorcycle; contrast tidak. Kategori two-wheeler ini tetap OPEN.'),
    7311: ('Motor/rider dekat bergerak menjauh di tengah dengan blur; car putih lebih jauh di kiri terlihat bersama lampu belakang merah. Gamma membuka detail jalan sekaligus menjadikan tekstur/noise gelap lebih terlihat; exposure membuat highlight merah/putih lebih dominan.',
        'Raw/gamma/contrast/unsharp mengeluarkan motorcycle+person dekat dan car jauh. Exposure kehilangan bbox car yang masih terlihat. Gamma mempertahankan tiga jenis bbox ini, tetapi confidence lebih rendah tidak diperlakukan sebagai metrik keberhasilan/kegagalan.'),
}

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def main():
    report = json.loads((SOURCE/'report.json').read_text())
    index = json.loads((HERE/'contact_index.json').read_text())
    checks=[]
    def check(name, condition):
        checks.append({'name':name,'passed':bool(condition)})
        assert condition, name
    check('all_declared_dev_samples_present', report['sample_indices']==FRAMES)
    check('source_holdout_not_evaluated', not report['heldout_evaluation_executed'])
    check('source_holdout_no_enhancement_inference', not report['holdout_enhancement_or_inference_executed'])
    check('source_no_temporal_pipeline', not report['temporal_pipeline_executed'])
    check('source_no_count_events', not report['count_events_generated'])
    check('contacts_bound_to_report', index['source_report_sha256']==sha(SOURCE/'report.json'))
    check('all30_contacts_and150_pixel_checks', len(index['sheets'])==30 and index['check_count']==150 and index['all_passed'])
    raws={s['frame_index']:s for s in report['source_frames']}
    variant_reports={v['variant']['name']:v for v in report['variants']}
    rows={}
    for v in VARIANTS:
        path=SOURCE/v/'frame_detections.jsonl.gz'
        check(f'{v}_detection_gzip_hash',sha(path)==variant_reports[v]['detections_sha256'])
        data=[json.loads(t) for t in gzip.open(path,'rt')]
        check(f'{v}_15_sample_order', [x['frame_index'] for x in data]==FRAMES)
        check(f'{v}_class_observation_totals',dict(Counter(d['class_name'] for x in data for d in x['detections']))==variant_reports[v]['detection_class_observation_totals'])
        rows[v]={x['frame_index']:x for x in data}
    reviewed=[]
    sheets={(x['frame_index'],x['kind']):x for x in index['sheets']}
    for f in FRAMES:
        source=SOURCE/'source_frames'/f'frame_{f:09d}.png'
        check(f'raw{f}_source_report_hash',sha(source)==raws[f]['sha256'])
        record={'frame_index':f,'claim_type':'ACTUAL_AI_ASSISTED_VISUAL_OBSERVATION_WITH_LIMITS',
                'raw_source_path':str(source.relative_to(SOURCE)), 'raw_source_sha256':sha(source),
                'visual_observation_id':f'dev_visual_f{f}',
                'photometric_observation':OBSERVATIONS[f][0], 'detection_observation':OBSERVATIONS[f][1],
                'variants':{},'actually_opened_contact_sheets':[]}
        for kind in ['transformed','annotated']:
            s=sheets[(f,kind)]
            check(f'contact{f}_{kind}_artifact_sha',sha(HERE/s['path'])==s['sha256'])
            record['actually_opened_contact_sheets'].append({'path':s['path'],'sha256':s['sha256'],'kind':kind})
            with Image.open(HERE/s['path']) as canvas:
                for tile in s['tiles']:
                    p=SOURCE/tile['source']
                    check(f'{f}_{tile["variant"]}_{kind}_artifact_sha',sha(p)==tile['source_sha256'])
                    with Image.open(p) as im:
                        expected=im.convert('RGB').crop(tuple(tile['source_crop_xyxy']))
                    check(f'{f}_{tile["variant"]}_{kind}_retained_native_pixels', canvas.crop(tuple(tile['sheet_tile_xyxy'])).tobytes()==expected.tobytes())
        for v in VARIANTS:
            row=rows[v][f]
            check(f'{f}_{v}_source_dims_identity_no_count',row['width']==1280 and row['height']==720 and row['input_video_sha256']==report['input_identity']['video_sha256'] and not row['accepted_count_event'])
            vr=next(s for s in variant_reports[v]['samples'] if s['frame_index']==f)
            for kind in ('transformed','annotated'):
                p=SOURCE/v/f'frame_{f:09d}_{kind}.png'
                check(f'{f}_{v}_{kind}_report_hash',sha(p)==vr[kind]['sha256'])
            record['variants'][v]={'detections':row['detections'], 'detections_reference':f'{v}/frame_detections.jsonl.gz',
                'detections_sha256':variant_reports[v]['detections_sha256'],
                'photometric_descriptors_original':vr['photometric_descriptors'],
                'transformed_sha256':vr['transformed']['sha256'], 'annotated_sha256':vr['annotated']['sha256']}
        reviewed.append(record)
    result={
        'review_version':'phase7_dev_visual_review_v1','source_run_id':report['run_id'],
        'reviewer':'AI_ASSISTED_CODEX_ACTUALLY_VIEWED_RETAINED_IMAGES',
        'scope':'15 DEV frames x five variants; all30 transformed/annotated native road/glare sheets viewed; six full native raw frames additionally viewed',
        'source_video_sha256':report['input_identity']['video_sha256'],
        'source_report_sha256':sha(SOURCE/'report.json'),'contact_index_sha256':sha(HERE/'contact_index.json'),
        'native_crop_xyxy':[0,360,1280,700],'crop_spatial_mapping':'sheet_xy translated to original native xy; no scaling/crop change between variants',
        'full_native_raw_frames_additionally_opened':[14,2277,2397,7072,7192,7252],
        'all_generated_sheets_actually_opened':True,'holdout_enhancement_reviewed':False,
        'new_model_or_tracker_or_encoder_execution':False,'vehicle_counts_or_quality_metrics_reported':False,
        'shortlist_proposal':{
            'claim_type':'PROPOSAL_FOR_CONTROLLED_TEMPORAL_EXPERIMENT_NOT_PRODUCTION_SELECTION',
            'variant':'gamma_070','parameters':{'gamma':0.7},
            'formula':report['formulae']['gamma'],
            'reason':'Gamma visibly lifts shadow/midtone road and truck underbody in DEV samples (0/14/7072/7132/7311), with less highlight expansion than the tested exposure gain. This provides a specific visibility hypothesis worth testing on continuous tracks; it does not win on sparse detection counts.',
            'raw_comparator_mandatory':True,
            'material_regressions_and_unknowns':['Frame14 visible motor loses motorcycle bbox compared with raw.','Frame2277 added car bbox overlaps visible near-motor front; category/component identity unresolved.','Frame2337 small background motorcycle bbox absent; physical identity of tiny bbox unresolved.','Frame7072 duplicate overlapping truck bboxes persist.','Frame7252 tiny two-wheeler bicycle/motorcycle disagreement remains unresolved.','Blur and burned-in metadata occlusion remain; gamma makes dark texture/noise more visible.'],
            'others_deferred':[{'variant':'exposure_125','reason':'Stronger observed highlight expansion; raw car at7311 no longer emitted; no temporal benefit established.'},{'variant':'contrast_125','reason':'Visible shadow detail is crushed in multiple road samples; vehicle motorcycle bbox absent at14/29; single truck bbox at7072 is not proof of downstream benefit.'},{'variant':'unsharp_s1_a05','reason':'Does not brighten shadow materially or remove motion blur; extra car2277 and class disagreement2397 remain; temporal benefit unknown.'}],
            'required_next_evidence':['Continuous raw vs gamma DEV replay with identical detector/tracker/ReID/counting controls and native geometry.','Compare same physical passages, measured vehicle BC crossing source, duplicates/merges, categories, missing support and regressions.','Freeze candidate before any hold-out enhancement/inference; no gamma production acceptance from this screening.']},
        'per_frame_reviews':reviewed,
        'descriptive_frame_observation_totals':{v:variant_reports[v]['detection_class_observation_totals'] for v in VARIANTS},
        'limits':['Sparse observations are not persistent tracks, unique physical vehicles or passage counts.','No ground truth, calibrated classification quality or accuracy/precision/recall/F1/MAPE result.','UNKNOWN small objects/headlights are not labeled false detections.','Prior Phase1 raw visual inspection means future hold-out is not blind; this review uses DEV enhancement only.','This review does not establish geometric alignment throughout a segment, tracker stability, ReID benefit, or counting improvement.']}
    (HERE/'visual_review.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
    validation={'method':'source artifact hashes, original report links, model observation totals and re-opened retained native contact pixels; no inference rerun',
        'check_count':len(checks),'passed':len(checks),'failed':0,'all_passed':True,'checks':checks,
        'visual_review_sha256':sha(HERE/'visual_review.json'),'method_source_sha256':sha(Path(__file__))}
    (HERE/'artifact_validation.json').write_text(json.dumps(validation,indent=2)+'\n')
    print(json.dumps({'reviewed_frames':15,'variants':5,'actually_opened_sheets':30,'artifact_checks_passed':len(checks),'recommended_temporal_probe':'gamma_070'}))

if __name__=='__main__':
    main()
